    // objectNamespace is the namespace for a JSON object.
    // In contrast to objectNameStack, this needs to remember all names
    // per JSON object.
    //
    // The zero value is an empty namespace ready for use.
    
    template<typename T> requires gocpp::GoStruct<T>
    objectNamespace::operator T()
    {
        T result;
        result.endOffsets = this->endOffsets;
        result.allUnquotedNames = this->allUnquotedNames;
        result.mapNames = this->mapNames;
        return result;
    }

    template<typename T> requires gocpp::GoStruct<T>
    bool objectNamespace::operator==(const T& ref) const
    {
        if (endOffsets != ref.endOffsets) return false;
        if (allUnquotedNames != ref.allUnquotedNames) return false;
        if (mapNames != ref.mapNames) return false;
        return true;
    }

    std::ostream& objectNamespace::PrintTo(std::ostream& os) const
    {
        os << '{';
        os << "" << endOffsets;
        os << " " << allUnquotedNames;
        os << " " << mapNames;
        os << '}';
        return os;
    }

    std::ostream& operator<<(std::ostream& os, const struct objectNamespace& value)
    {
        return value.PrintTo(os);
    }

    // reset resets the namespace to be empty.
    void rec::reset(objectNamespace* ns)
    {
        ns->endOffsets = ns->endOffsets.make_slice(0, 0);
        ns->allUnquotedNames = ns->allUnquotedNames.make_slice(0, 0);
        ns->mapNames = nullptr;
        if(cap(ns->endOffsets) > (1 << 6))
        {
            // avoid pinning arbitrarily large amounts of memory
            ns->endOffsets = nullptr;
        }
        if(cap(ns->allUnquotedNames) > (1 << 10))
        {
            // avoid pinning arbitrarily large amounts of memory
            ns->allUnquotedNames = nullptr;
        }
    }

    // length reports the number of names in the namespace.
    int rec::length(objectNamespace* ns)
    {
        return len(ns->endOffsets);
    }

    // getUnquoted retrieves the ith unquoted name in the namespace.
    gocpp::slice<unsigned char> rec::getUnquoted(objectNamespace* ns, int i)
    {
        if(i == 0)
        {
            return ns->allUnquotedNames.make_slice(0, ns->endOffsets[0]);
        }
        else
        {
            return ns->allUnquotedNames.make_slice(ns->endOffsets[i - 1], ns->endOffsets[i]);
        }
    }

    // lastUnquoted retrieves the last name in the namespace.
    gocpp::slice<unsigned char> rec::lastUnquoted(objectNamespace* ns)
    {
        return rec::getUnquoted(gocpp::recv(ns), rec::length(gocpp::recv(ns)) - 1);
    }

    // insertQuoted inserts a name and reports whether it was inserted,
    // which only occurs if name is not already in the namespace.
    // The provided name must be a valid JSON string.
    bool rec::insertQuoted(objectNamespace* ns, gocpp::slice<unsigned char> name, bool isVerbatim)
    {
        if(isVerbatim)
        {
            name = name.make_slice(len("\""_s), len(name) - len("\""_s));
        }
        return rec::insert(gocpp::recv(ns), name, ! isVerbatim);
    }

    bool rec::InsertUnquoted(objectNamespace* ns, gocpp::slice<unsigned char> name)
    {
        return rec::insert(gocpp::recv(ns), name, false);
    }

