    bool rec::insert(objectNamespace* ns, gocpp::slice<unsigned char> name, bool quoted)
    {
        gocpp::slice<unsigned char> allNames = {};
        if(quoted)
        {
            std::tie(allNames, std::ignore) = jsonwire::AppendUnquote(ns->allUnquotedNames, name);
        }
        else
        {
            allNames = append(ns->allUnquotedNames, name);
        }
        name = allNames.make_slice(len(ns->allUnquotedNames));

        // Switch to a map if the buffer is too large for linear search.
        // This does not add the current name to the map.
        if(ns->mapNames == nullptr && (rec::length(gocpp::recv(ns)) > 64 || len(ns->allUnquotedNames) > 1024))
        {
            ns->mapNames = gocpp::make(gocpp::Tag<gocpp::map<gocpp::string, gocpp_id_1>>());
            unsigned int startOffset = {};
            for(auto [gocpp_ignored, endOffset] : ns->endOffsets)
            {
                auto name = ns->allUnquotedNames.make_slice(startOffset, endOffset);
                // allocates a new string
                ns->mapNames[gocpp::string(name)] = gocpp_id_2 {};
                startOffset = endOffset;
            }
        }

        if(ns->mapNames == nullptr)
        {
            // Perform linear search over the buffer to find matching names.
            // It provides O(n) lookup, but does not require any allocations.
            unsigned int startOffset = {};
            for(auto [gocpp_ignored, endOffset] : ns->endOffsets)
            {
                if(gocpp::string(ns->allUnquotedNames.make_slice(startOffset, endOffset)) == gocpp::string(name))
                {
                    return false;
                }
                startOffset = endOffset;
            }
        }
        else
        {
            // Use the map if it is populated.
            // It provides O(1) lookup, but requires a string allocation per name.
            if(auto [gocpp_id_3, ok] = ns->mapNames[gocpp::string(name)]; ok)
            {
                return false;
            }
            // allocates a new string
            ns->mapNames[gocpp::string(name)] = gocpp_id_4 {};
        }

        ns->allUnquotedNames = allNames;
        ns->endOffsets = append(ns->endOffsets, (unsigned int)(len(ns->allUnquotedNames)));
        return true;
    }

    // removeLast removes the last name in the namespace.
    void rec::removeLast(objectNamespace* ns)
    {
        if(ns->mapNames != nullptr)
        {
            remove(ns->mapNames, gocpp::string(rec::lastUnquoted(gocpp::recv(ns))));
        }
        if(rec::length(gocpp::recv(ns)) - 1 == 0)
        {
            ns->endOffsets = ns->endOffsets.make_slice(0, 0);
            ns->allUnquotedNames = ns->allUnquotedNames.make_slice(0, 0);
        }
        else
        {
            ns->endOffsets = ns->endOffsets.make_slice(0, rec::length(gocpp::recv(ns)) - 1);
            ns->allUnquotedNames = ns->allUnquotedNames.make_slice(0, ns->endOffsets[rec::length(gocpp::recv(ns)) - 1]);
        }
    }

